/* ===================== 4. CLIENT (OPERATOR) SCREENS ===================== */
/* ---------- who is signed in ---------- */
const ME=()=>S.op?byId(DB.operators,S.op):null;
window.CUR_OP=()=>S.op;window.CUR_OPN=()=>ME()&&ME().name;
const myInbox=()=>(DB.inbox||[]).filter(n=>n.to==='client:'+S.op);
const approved=()=>{const o=ME();return!!o&&o.kyc==='APPROVED'};
function gateOk(p){return!S.op||approved()||['kyc','notifications','company'].includes(p)}
const myTrips=()=>DB.trips.filter(t=>t.operatorId===S.op);
const myBuses=()=>DB.buses.filter(b=>b.operatorId===S.op);
const myBk=()=>DB.bookings.filter(b=>b.operatorId===S.op);
const myCrew=()=>DB.opStaff.filter(s=>s.operatorId===S.op);
const myDrivers=()=>myCrew().filter(s=>s.role==='DRIVER'&&s.status==='ACTIVE');
const myRoutes=()=>{const u=new Set(myTrips().map(t=>t.routeId));return DB.routes.filter(r=>r.operatorId===S.op||u.has(r.id))};
const sameDay=(a,b)=>new Date(a).toDateString()===new Date(b).toDateString();
const audit=(action,target)=>DB.audit.unshift({id:uid('AU'),at:new Date().toISOString(),who:(ME()?ME().name:'Partner')+' ('+ROLES[S.role]+')',role:'OPERATOR',action:'Partner: '+action,target,ip:'49.37.12.8',sensitive:/cancel|bank|delete/i.test(action)});
/* customer price = operator fare + Abra commission + GST + convenience fee */
function commFor(route,type){const o=ME(),L=DB.commissions.filter(c=>c.status==='ACTIVE');return L.find(c=>c.scope==='OPERATOR'&&o&&c.target===o.name)||L.find(c=>c.scope==='ROUTE'&&c.target===route)||L.find(c=>c.scope==='BUS_TYPE'&&c.target===type)||Object.assign({scope:'DEFAULT',target:'Default rule'},DB.commissionDefault)}
function price(fare,route,type){const c=commFor(route,type),cm=c.mode==='PERCENT'?Math.round(fare*c.value/10000):c.value,gst=Math.round((fare+cm)*.05),fee=DB.payoutCfg.fee;return{fare,cm,gst,fee,total:fare+cm+gst+fee,rule:c}}
const ruleTxt=c=>(c.mode==='PERCENT'?c.value/100+'%':money(c.value)+' per seat')+' ('+lab(c.scope)+(c.target&&c.scope!=='DEFAULT'?': '+c.target:'')+')';
const conflict=(driver,depart,except)=>myTrips().find(t=>t.id!==except&&t.driver===driver&&!['CANCELLED','ARRIVED'].includes(t.status)&&Math.abs(new Date(t.depart)-new Date(depart))<10*36e5);
const sstrip=t=>`<span class="sm m">${t.booked}/${t.seats}</span>`;

/* ---------- sign in, invitation ---------- */
function authHtml(){const inv=DB.invitations.filter(i=>i.status==='PENDING');
if(S.authInv){const i=byId(DB.invitations,S.authInv);return`<div class="auth"><div class="c authc"><div class="brand">${ic('bus',26)}<b>Abra Partner Portal</b></div><h2>Accept your invitation</h2><p class="m">You were invited to manage <b>${esc(i.company)}</b> on Abra Travels. Choose a password to create your account.</p>
<div class="fgrid">${fld('an','Your name',i.owner,{req:1,full:1})}${fld('ap','Password','',{type:'password',req:1,full:1,h:'At least 8 characters with a number.'})}${fld('ap2','Repeat password','',{type:'password',req:1,full:1})}</div>
<label class="row sm mt2"><input type="checkbox" class="ckb" id="f_at"> I accept the partner terms</label><div class="row mt"><button class="cta gh" data-a="au_back">Back</button><button class="cta grow" data-a="au_acc" data-v="${i.id}">Create account</button></div></div></div>`}
return`<div class="auth"><div class="c authc"><div class="brand">${ic('bus',26)}<b>Abra Partner Portal</b></div><h2>Sign in</h2><p class="m">Demo: choose which bus company to sign in as. Companies waiting for KYC open only the KYC screen.</p>
<div class="fd"><label for="f_so">Company account</label><select id="f_so">${DB.operators.map(o=>`<option value="${o.id}">${esc(o.name)} · ${o.kyc==='APPROVED'?lab(o.status):'KYC '+lab(o.kyc).toLowerCase()}</option>`).join('')}</select></div>
${fld('spw','Password','',{type:'password',ph:'Any password works in the demo'})}
<button class="cta mt2" style="width:100%" data-a="au_in">Sign in</button><button class="cta gh mt2" style="width:100%" data-a="au_in">Continue with Google</button>
<div class="hrl"></div><h3>Invited by Abra?</h3>${inv.length?`<div class="col mt2">${inv.map(i=>`<button class="doc row" style="text-align:left" data-a="au_inv" data-v="${i.id}">${ic('mail')}<div class="grow"><b>${esc(i.company)}</b><div class="sm m">${esc(i.email)} · link expires ${fd(i.expiresAt)}</div></div>${ic('chevR',16)}</button>`).join('')}</div>`:`<p class="sm m">No open invitations. Send one from the admin app (Invitations).</p>`}</div></div>`}
A.au_in=()=>{S.op=gv('so');S.role='SUPER_ADMIN';persist();navigate(approved()?'dashboard':'kyc');toast('Signed in as '+ME().name)};
A.au_inv=v=>{S.authInv=v;render()};A.au_back=()=>{S.authInv=null;render()};
A.au_acc=v=>{const i=byId(DB.invitations,v);if(!chk([['an','Name'],['ap','Password',x=>x.length<8||!/\d/.test(x)?'Use 8 or more characters with a number':''],['ap2','Repeat password',x=>x!==gv('ap')?'The passwords do not match':'']]))return;if(!$('#f_at').checked)return toast('Accept the partner terms to continue');
const id=uid('OP');DB.operators.push({id,name:i.company,owner:gv('an'),email:i.email,phone:'',city:'',status:'PENDING_APPROVAL',buses:0,trips:0,joined:new Date().toISOString(),payout:DB.payoutCfg.defaultMode,gst:'',rating:'-',bank:{holder:'',acc:'',ifsc:'',status:'PENDING'},kyc:'DRAFT',fund:'PLATFORM'});
DB.opUsers.push({id:uid('OU'),operatorId:id,name:gv('an'),email:i.email,role:'SUPER_ADMIN',status:'ACTIVE',last:new Date().toISOString()});i.status='ACCEPTED';S.authInv=null;S.op=id;S.role='SUPER_ADMIN';persist();navigate('kyc');toast('Account created. Complete your KYC.')};

/* ---------- DASHBOARD ---------- */
reg('dashboard','Dashboard','home',()=>{const o=ME(),T=myTrips(),B=myBk(),days=Array.from({length:14},(_,i)=>new Date(NOW-(13-i)*DAY));
const per=days.map(d=>B.filter(b=>sameDay(b.at,d)).length),rev=days.map(d=>B.filter(b=>sameDay(b.at,d)&&b.status!=='CANCELLED').reduce((a,b)=>a+b.amount-b.commission,0));
const up=T.filter(t=>new Date(t.depart)>NOW&&!['CANCELLED','DRAFT'].includes(t.status)),occ=Math.round(T.filter(t=>t.status!=='DRAFT').reduce((a,t)=>a+t.booked/t.seats,0)/Math.max(1,T.filter(t=>t.status!=='DRAFT').length)*100);
const rmap={};T.filter(t=>t.status!=='DRAFT').forEach(t=>{rmap[t.route]=rmap[t.route]||{l:t.route,b:0,s:0};rmap[t.route].b+=t.booked;rmap[t.route].s+=t.seats});const occR=Object.values(rmap).map(r=>({l:r.l,v:Math.round(r.b/r.s*100)})).sort((a,b)=>b.v-a.v).slice(0,6);
const al=[];const exI=myBuses().filter(b=>new Date(b.insExp)-NOW<30*DAY);if(exI.length)al.push(['r','file',exI.length+' bus insurance document(s) expire within 30 days','buses']);
const exL=myCrew().filter(s=>s.licExp&&new Date(s.licExp)-NOW<30*DAY);if(exL.length)al.push(['r','user',exL.length+' driver licence(s) expire within 30 days','crew']);
const dr=T.filter(t=>t.status==='DRAFT').length;if(dr)al.push(['a','cal',dr+' trip(s) still in draft, customers cannot book them','trips']);
const nd=up.filter(t=>!t.driver).length;if(nd)al.push(['a','user',nd+' upcoming trip(s) without a driver','trips']);
const pb=myBuses().filter(b=>b.status==='PENDING_APPROVAL').length;if(pb)al.push(['b','bus',pb+' bus(es) waiting for Abra approval','buses']);
const lo=up.filter(t=>t.booked/t.seats<.3&&new Date(t.depart)-NOW<2*DAY).length;if(lo)al.push(['a','chart',lo+' trip(s) in the next 2 days are less than 30% full. Consider an offer.','offers']);
const sq=DB.sos.filter(s=>T.some(t=>t.id===s.trip)&&['NEW','ACKNOWLEDGED','RESPONDING'].includes(s.status)).length;if(sq)al.push(['r','alert',sq+' open SOS on your buses','live']);
return`<div class="page">${ph('Hello, '+esc(o.owner.split(' ')[0]),esc(o.name)+' · '+(o.status==='SUSPENDED'?'<b style="color:var(--rtx)">Suspended by Abra</b>':'verified partner'),btn('go','trips','New trip','plus','','trips'))}
${o.status==='SUSPENDED'?hb('Your account is suspended. Customers cannot see your trips. Contact Abra support.','r','alert'):''}
<div class="kg">${kc('ticket',num(B.filter(b=>sameDay(b.at,NOW)).length),'Bookings today','')}${kc('wallet',inrs(rev.slice(-7).reduce((a,b)=>a+b,0)),'Your earnings, 7 days','')}${kc('chart',occ+'%','Average occupancy','')}${kc('cal',up.length,'Upcoming trips','')}${kc('bus',myBuses().filter(b=>b.status==='ACTIVE').length,'Active buses','')}${kc('nav',DB.live.filter(l=>T.some(t=>t.id===l.tripId)).length,'Buses live now','')}${kc('users',myDrivers().length,'Drivers on duty','')}${kc('star',o.rating,'Customer rating','')}</div>
${al.length?`<div class="c"><h3>Needs your attention</h3><div class="col">${al.map(a=>`<button class="doc row" style="text-align:left" data-a="go" data-v="${a[3]}"><span class="st ${a[0]}">${ic(a[1],14)}</span><span class="grow">${a[2]}</span>${ic('chevR',16)}</button>`).join('')}</div></div>`:''}
<div class="g21"><div class="c"><h3>Bookings, last 14 days</h3>${lineChart([{n:'Bookings',d:per}],days.map(d=>d.getDate()+'/'+(d.getMonth()+1)),{area:1,t:'Bookings per day',link:{page:'bookings'}})}</div><div class="c"><h3>Booking status</h3>${donut([['Confirmed','CONFIRMED'],['Completed','COMPLETED'],['Cancelled','CANCELLED']].map(([l,s])=>({l,s,v:B.filter(b=>b.status===s).length})),{rows:it=>B.filter(b=>b.status===it.s),link:{page:'bookings',t:'cbk',k:'status',val:it=>it.s}})}</div></div>
<div class="g2"><div class="c"><h3>Your earnings per day (after commission)</h3>${lineChart([{n:'Earnings',d:rev}],days.map(d=>d.getDate()+'/'+(d.getMonth()+1)),{fmt:v=>'₹'+Math.round(v/100000)+'k',t:'Earnings',link:{page:'earnings'}})}</div><div class="c"><h3>Occupancy by route</h3>${barChart(occR,{fmt:v=>v+'%',rows:it=>B.filter(b=>b.route===it.l),link:{page:'trips'}})}</div></div></div>`},()=>myInbox().filter(n=>!n.read).length);

/* ---------- KYC ---------- */
const myKyc=()=>DB.submissions.filter(s=>s.operatorId===S.op&&s.type==='COMPANY').sort((a,b)=>new Date(b.submittedAt)-new Date(a.submittedAt))[0];
const kd=()=>{const o=ME();o.kycDraft=o.kycDraft||{answers:{},docs:{}};return o.kycDraft};
const kQs=()=>DB.questions.filter(q=>q.applies==='OPERATOR'&&q.active).sort((a,b)=>a.order-b.order);
function ruleOk(c,ans){if(!c||/^always$/i.test(c))return true;let m=c.match(/^(\w+)\s*=\s*(.+)$/);if(m)return String(ans[m[1]]||'')===m[2].trim();m=c.match(/^(\w+)\s+includes\s+(.+)$/);if(m)return[].concat(ans[m[1]]||[]).includes(m[2].trim());return true}
function kDocs(){const ans=kd().answers;return DB.docTypes.filter(d=>d.applies==='OPERATOR'&&d.active).map(d=>{const rs=DB.rules.filter(r=>r.active&&r.doc===d.key);if(!rs.length)return{...d,need:d.required};const hit=rs.filter(r=>ruleOk(r.cond,ans));return hit.length?{...d,need:hit.some(r=>r.required)}:null}).filter(Boolean)}
const chipQ=(q,v,on)=>`<button class="ch ${on?'on':''}" data-a="kq" data-v="${esc(q.key+'|'+v)}">${esc(v)}</button>`;
function qHtml(q){const a=kd().answers[q.key];let i;
if(q.type==='BOOLEAN')i=['Yes','No'].map(v=>chipQ(q,v,a===v)).join('');
else if(q.type==='SINGLE_CHOICE')i=q.opts.split(',').map(x=>x.trim()).map(v=>chipQ(q,v,a===v)).join('');
else if(q.type==='MULTI_CHOICE')i=q.opts.split(',').map(x=>x.trim()).map(v=>chipQ(q,v,[].concat(a||[]).includes(v))).join('');
else i=`<input class="kin" data-live="kq_in" data-k="${q.key}" type="${q.type==='NUMBER'?'number':'text'}" value="${esc(a||'')}" aria-label="${esc(q.label)}">`;
return`<div class="kq"><b>${esc(q.label)}${q.required?' *':` <span class="m sm">(optional)</span>`}</b><div class="row rw mt2">${i}</div></div>`}
A.kq=v=>{const[k,val]=v.split('|'),q=DB.questions.find(x=>x.key===k),a=kd().answers;if(q.type==='MULTI_CHOICE'){const l=[].concat(a[k]||[]);a[k]=l.includes(val)?l.filter(x=>x!==val):l.concat(val)}else a[k]=val;render()};
A.kq_in=(v,el)=>{kd().answers[el.dataset.k]=v;AbraStore.set(DB);AbraStore.save('client')};
const kSt=(d,s)=>{const x=s&&s.docs.find(y=>y.key===d.key);if(x)return x.status;return kd().docs[d.key]?'UPLOADED':'NOT_UPLOADED'};
const KST={NOT_UPLOADED:['Not uploaded','n'],UPLOADED:['Uploaded','b'],PENDING:['In review','a'],ACCEPTED:['Accepted','g'],REJECTED:['Rejected','r']};
reg('kyc','KYC verification','shield',()=>{const o=ME(),s=myKyc(),st=o.kyc==='APPROVED'?'APPROVED':s?s.status:'DRAFT',step=S.ui.kstep||1;let b='';
if(st==='APPROVED')b=`${hb('<b>Your company is verified.</b> Buses, trips, staff and sales are open.','g','shield')}<div class="c"><h3>Your documents</h3>${s?`<div class="col">${s.docs.map(d=>`<div class="row bt doc"><div>${ic('file',16)} <b>${esc(d.name)}</b>${d.expiry?`<div class="sm m">Expires ${fd(d.expiry)}</div>`:''}</div>${chip('ACCEPTED')}</div>`).join('')}</div>`:'<p class="m">Verified by the Abra team.</p>'}<p class="sm m">To change a verified document, contact Abra support. Bus documents are managed in Buses.</p></div>`;
else if(st==='PENDING')b=`<div class="c tc"><div class="empty"><div class="big" style="background:var(--abg);color:var(--atx)">${ic('clock',30)}</div><h3>Under verification</h3><p class="m">The Abra team is reviewing your documents, usually within 1 to 2 working days. This screen updates by itself when they decide.</p></div>
<div class="tl" style="text-align:left;max-width:420px;margin:auto">${(s.history||[]).map(h=>`<div class="ev g"><b>${esc(h[0])}</b><div class="sm m">${fdt(h[1])}</div></div>`).join('')}<div class="ev a"><b>Review in progress</b></div><div class="ev"><b>Decision</b><div class="sm m">You will be notified here, by email and on WhatsApp</div></div></div></div>
<div class="c"><h3>What you sent</h3>${s.docs.map(d=>`<div class="row bt doc"><span>${ic('file',16)} ${esc(d.name)} <span class="sm m">${esc(d.file)}</span></span><span class="st ${KST[d.status][1]}">${KST[d.status][0]}</span></div>`).join('')}</div>`;
else if(st==='REJECTED'){const left=s.docs.filter(d=>d.status==='REJECTED'&&!d.fixed).length;
b=`${hb('<b>Some documents need fixing.</b> Replace only the rejected ones, then send them again. Accepted documents and your answers are locked.','r','alert')}<div class="g2">${s.docs.map((d,i)=>`<div class="c"><div class="row bt"><b>${esc(d.name)}</b>${d.fixed?chip('Replaced','b'):chip(d.status)}</div>${d.status==='REJECTED'&&!d.fixed?`<div class="hb r sm">${esc(d.reason)}</div><button class="cta sm" data-a="kd_fix" data-v="${i}">${ic('upload',14)} Replace</button>`:`<p class="sm m">${esc(d.file)}${d.status==='ACCEPTED'?' · locked':''}</p>`}</div>`).join('')}</div>
<div class="c row bt"><span class="m">${left?left+' document(s) still to replace':'All corrections are ready.'}</span><button class="cta" data-a="kd_resend" ${left?'disabled':''}>Send corrections</button></div>`}
else{const Q=kQs(),D=kDocs(),qOk=Q.filter(q=>q.required).every(q=>{const a=kd().answers[q.key];return a&&[].concat(a).length}),dOk=D.filter(d=>d.need).every(d=>kd().docs[d.key]);
const stp=`<div class="steps3">${['Your company','Documents','Submit'].map((l,i)=>`<button class="${step===i+1?'on':''} ${i+1<step?'done':''}" data-a="kstep" data-v="${i+1}"><span>${i+1<step?ic('check',14):i+1}</span>${l}</button>`).join('')}</div>`;
if(step===1)b=stp+`<div class="c col">${fld('kcn','Company name',o.name,{req:1})}${Q.map(qHtml).join('')}<p class="sm m">These questions are set by Abra (admin app, KYC questionnaire). Your answers decide which documents you need.</p></div><div class="row"><button class="cta" data-a="kstep" data-v="2" ${qOk?'':'disabled'}>Save and see documents ${ic('chevR',16)}</button>${qOk?'':'<span class="sm m">Answer the required questions (*)</span>'}</div>`;
if(step===2)b=stp+`<div class="g2">${D.map(d=>{const f=kd().docs[d.key];return`<div class="c"><div class="row bt"><b>${esc(d.name)}${d.need?' *':' <span class="m sm">(optional)</span>'}</b>${f?chip('Uploaded','b'):chip('Not uploaded','n')}</div><p class="sm m">${esc(d.instr)} · ${esc(d.types)}, up to ${d.maxMb} MB</p>${f?`<div class="doc sm">${ic('file',14)} ${esc(f.file)}</div>`:''}<button class="cta sm gh" data-a="kd_up" data-v="${d.key}">${ic('upload',14)} ${f?'Replace':'Upload'}</button></div>`}).join('')}</div><div class="row"><button class="cta gh" data-a="kstep" data-v="1">${ic('chevL',16)} Edit answers</button><button class="cta" data-a="kstep" data-v="3" ${dOk?'':'disabled'}>Review and submit ${ic('chevR',16)}</button></div>`;
if(step===3)b=stp+`<div class="c">${kvl(Object.fromEntries(Q.map(q=>[q.label,esc([].concat(kd().answers[q.key]||'-').join(', '))])))}<h4 class="mt">Documents</h4>${D.filter(d=>kd().docs[d.key]).map(d=>`<div class="sm">${ic('check',14)} ${esc(d.name)}: ${esc(kd().docs[d.key].file)}</div>`).join('')}</div>${hb('After you submit, your answers and documents are locked until Abra decides.','b','lock')}<div class="row"><button class="cta gh" data-a="kstep" data-v="2">${ic('chevL',16)} Back</button><button class="cta ok" data-a="kd_submit">Submit for verification</button></div>`}
return`<div class="page">${ph('KYC verification',st==='APPROVED'?'Verified':st==='PENDING'?'Waiting for Abra':st==='REJECTED'?'Needs fixing':'Step '+step+' of 3','',[['Company'],['KYC']])}${st!=='APPROVED'?hb('Dashboard, buses, trips and sales open after Abra approves your company.','b','lock'):''}${b}</div>`});
A.kstep=v=>{const n=Number(v);if(n>=2&&!gv('kcn')&&S.ui.kstep===1)return setErr('kcn','Company name is required');if(S.ui.kstep===1&&gv('kcn'))ME().name=gv('kcn');S.ui.kstep=n;render()};
const UPOPT=[['ok','scan.pdf · 1.2 MB'],['type','photo.heic · 2 MB (wrong type)'],['big','scan.pdf · 18 MB (too large)']];
function upDlg(title,info,run){S.upRun=run;openModal({t:title,w:'sm2',b:`<p class="m">${info}</p><div class="doc tc"><input type="file" id="upf" accept=".pdf,.jpg,.jpeg,.png"><p class="sm m mt2">or pick an example</p><div class="col">${UPOPT.map(([k,l])=>`<button class="cta gh sm" data-a="up_ex" data-v="${k}">${ic('file',14)} ${l}</button>`).join('')}</div></div><div id="uperr"></div>`,f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="up_go">Upload</button>`})}
A.up_ex=v=>{S.upPick=v;$('#uperr').innerHTML=v==='ok'?hb('scan.pdf is ready to upload.','g','check'):hb(v==='type'?'This file type is not allowed. Use PDF, JPG or PNG.':'The file is larger than 5 MB.','r','alert')};
A.up_go=()=>{const f=$('#upf')&&$('#upf').files[0];let name='scan.pdf';if(f){if(!/\.(pdf|jpe?g|png)$/i.test(f.name))return A.up_ex('type');if(f.size>5*1048576)return A.up_ex('big');name=f.name}else if(S.upPick!=='ok')return toast(S.upPick?'Fix the file first':'Choose a file or an example');S.upPick=null;const r=S.upRun;closeModal();r(name);render();toast('Uploaded')};
A.kd_up=v=>{const d=DB.docTypes.find(x=>x.key===v);upDlg(d.name,esc(d.instr)+' '+esc(d.types)+', up to '+d.maxMb+' MB.',n=>{kd().docs[v]={file:n,at:new Date().toISOString()}})};
A.kd_submit=()=>{const o=ME(),D=kDocs().filter(d=>kd().docs[d.key]);confirmD({t:'Submit for verification',msg:'Your answers and '+D.length+' documents go to the Abra team.',ok:'Submit',tone:'ok',run:()=>{
DB.submissions.unshift({id:uid('SUB'),operatorId:o.id,operator:o.name,type:'COMPANY',status:'PENDING',submittedAt:new Date().toISOString(),docs:D.map(d=>({key:d.key,name:d.name,file:kd().docs[d.key].file,status:'PENDING',reason:'',expiry:d.expires?new Date(NOW+365*DAY).toISOString().slice(0,10):''})),answers:kQs().map(q=>[q.label,[].concat(kd().answers[q.key]||'-').join(', ')]),history:[['Submitted',new Date().toISOString()]]});
o.kyc='PENDING';audit('Submitted KYC',o.id);render();toast('Sent. Abra is reviewing your documents.')}})};
A.kd_fix=v=>{const s=myKyc(),d=s.docs[Number(v)];upDlg('Replace '+d.name,'Reason from Abra: '+esc(d.reason),n=>{d.file=n;d.fixed=true})};
A.kd_resend=()=>{const s=myKyc();s.docs.forEach(d=>{if(d.fixed){d.status='PENDING';d.reason='';delete d.fixed}});s.status='PENDING';s.history.push(['Corrections sent',new Date().toISOString()]);ME().kyc='PENDING';audit('Sent KYC corrections',s.id);render();toast('Corrections sent for review')};

/* ---------- COMPANY PROFILE ---------- */
reg('company','Company profile','brief',()=>{const o=ME();return`<div class="page">${ph('Company profile','Details customers and Abra see.','',[['Company'],['Profile']])}
<div class="g2"><div class="c"><h3>Company</h3><div class="fgrid">${fld('cn','Company name',o.name,{req:1})}${fld('co','Owner name',o.owner,{req:1})}${fld('ce','Email',o.email,{type:'email',req:1})}${fld('cp','Support phone',o.phone)}${fld('cc','City',o.city)}${fld('cg','GSTIN',o.gst)}</div><div class="row">${btn('co_save','','Save','check','','company')}</div></div>
<div class="c"><h3>Bank account for payouts</h3>${hb('Changing the bank account pauses payouts until Abra verifies it.','a','info')}<div class="fgrid">${fld('bh','Account holder',o.bank.holder)}${fld('ba','Account number',o.bank.acc)}${fld('bi','IFSC',o.bank.ifsc)}</div><div class="row bt"><span>Status ${chip(o.bank.status)}</span>${btn('bk_save','','Save bank details','check','','company')}</div>
<div class="sm m">Payout mode: <b>${o.payout==='AUTO'?'Automatic (Razorpay Route)':'Manual settlement'}</b>, set by Abra.</div></div></div></div>`});
A.co_save=()=>{if(!chk([['cn','Company name'],['co','Owner name'],['ce','Email',x=>/^\S+@\S+\.\S+$/.test(x)?'':'Enter a valid email']]))return;Object.assign(ME(),{name:gv('cn'),owner:gv('co'),email:gv('ce'),phone:gv('cp'),city:gv('cc'),gst:gv('cg')});audit('Updated company profile',S.op);render();toast('Saved')};
A.bk_save=()=>{if(!chk([['bh','Account holder'],['ba','Account number',x=>/^\d{6,18}$/.test(x.replace(/X/g,'1'))?'':'Enter 6 to 18 digits'],['bi','IFSC',x=>/^[A-Z]{4}0[A-Z0-9]{6}$/i.test(x)?'':'Looks wrong, for example HDFC0001234']]))return;const o=ME();o.bank={holder:gv('bh'),acc:gv('ba'),ifsc:gv('bi').toUpperCase(),status:'PENDING'};audit('Changed bank account',S.op);AbraStore.notify('admin','Bank account changed',o.name+' changed the payout bank account. Verify it.','payout','wallet');render();toast('Saved. Abra will verify the account.')};

/* ---------- BUSES ---------- */
const busSub=b=>DB.submissions.filter(s=>s.type==='BUS'&&s.bus===b.reg).sort((x,y)=>new Date(y.submittedAt)-new Date(x.submittedAt))[0];
reg('buses','Buses','bus',()=>{const L=myBuses();return`<div class="page">${ph('Buses','Every bus needs Abra approval before it can run trips.',btn('bus_new','','Add bus','plus','','buses')+btn('imp','buses','Import','upload','gh','buses'),[['Fleet'],['Buses']])}
<div class="kg">${kc('bus',L.length,'Buses','')}${kc('check',L.filter(b=>b.status==='ACTIVE').length,'Active','')}${kc('clock',L.filter(b=>b.status==='PENDING_APPROVAL').length,'Waiting for approval','')}${kc('file',L.filter(b=>new Date(b.insExp)-NOW<30*DAY).length,'Insurance expiring in 30 days','')}</div>
${tbl('cbus',[{k:'reg',l:'Registration',r:x=>`<b>${esc(x.reg)}</b><div class="sm m">${esc(x.name)}</div>`},{k:'type',l:'Type'},{k:'seats',l:'Seats'},{k:'layout',l:'Layout'},{k:'insExp',l:'Insurance',r:x=>new Date(x.insExp)<NOW?chip('Expired','r'):new Date(x.insExp)-NOW<30*DAY?chip('Expires '+fd(x.insExp),'a'):fd(x.insExp),v:x=>x.insExp},{k:'status',l:'Status',r:x=>{const s=busSub(x);return chip(x.status)+(s&&s.status==='REJECTED'?' '+chip('Fix documents','r'):'')}}],L,{row:'bus_open',filters:[{k:'status',l:'Status',opts:['ACTIVE','PENDING_APPROVAL','MAINTENANCE','RETIRED']}],exp:'my_buses',emptyT:'No buses yet',emptyS:'Add your first bus to start selling seats.'})}</div>`});
function busForm(b){b=b||{reg:'',name:'',type:DB.busTypes[0].name,seats:40,layout:'2+2 Seater',amen:[]};return`<div class="fgrid">${fld('br','Registration number',b.reg,{req:1,ph:'TS09 UB 1234',dis:!!b.id})}${fld('bn','Bus name',b.name,{req:1,ph:'Kaveri Gold 12'})}${fld('bt','Bus type',b.type,{type:'select',opts:DB.busTypes.filter(t=>t.active).map(t=>t.name)})}${fld('bs','Seats',b.seats,{type:'number',min:10,max:60,req:1})}${fld('bl','Seat layout',b.layout,{type:'select',opts:['2+2 Seater','2+1 Sleeper','1+2 Sleeper','2+1 Semi-sleeper']})}${fld('bx','Insurance valid till',b.insExp?b.insExp.slice(0,10):new Date(NOW+300*DAY).toISOString().slice(0,10),{type:'date',req:1})}
<div class="full"><b class="sm">Amenities</b><div class="row rw mt2">${DB.amenities.filter(a=>a.active).map(a=>`<label class="ch"><input type="checkbox" class="ckb bam" value="${esc(a.name)}" ${(b.amen||[]).includes(a.name)?'checked':''}> ${esc(a.name)}</label>`).join('')}</div></div></div>`}
A.bus_new=()=>{S.busDocs={};const D=DB.docTypes.filter(d=>d.applies==='BUS'&&d.active);openModal({t:'Add bus',w:'wide',b:busForm()+`<h4 class="mt">Documents for Abra (${D.length})</h4><div class="g2">${D.map(d=>`<div class="doc row bt"><span>${esc(d.name)}${d.required?' *':''}</span><button class="cta sm gh" data-a="bdoc" data-v="${d.key}" id="bd_${d.key}">${ic('upload',14)} Attach</button></div>`).join('')}</div>`,f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="bus_save">Send for approval</button>`})};
A.bdoc=v=>{S.busDocs[v]=v+'_scan.pdf';const e=$('#bd_'+v);if(e){e.innerHTML=ic('check',14)+' Attached';e.classList.add('ok')}};
A.bus_save=v=>{const isNew=!v;if(!chk([['br','Registration number',x=>/^[A-Z]{2}\s?\d{2}\s?[A-Z]{1,3}\s?\d{4}$/i.test(x)?(isNew&&DB.buses.some(b=>b.reg.replace(/\s/g,'')===x.replace(/\s/g,'').toUpperCase())?'This bus is already registered':''):'Use the format TS09 UB 1234'],['bn','Bus name'],['bs','Seats',x=>Number(x)>=10&&Number(x)<=60?'':'10 to 60 seats']]))return;
const amen=$$('.bam').filter(x=>x.checked).map(x=>x.value);
if(isNew){const miss=DB.docTypes.filter(d=>d.applies==='BUS'&&d.active&&d.required&&!S.busDocs[d.key]);if(miss.length)return toast('Attach: '+miss.map(d=>d.name).join(', '));
const o=ME(),reg=gv('br').toUpperCase(),bt=DB.busTypes.find(t=>t.name===gv('bt'));DB.buses.unshift({id:uid('BUS'),operatorId:o.id,operator:o.name,reg,name:gv('bn'),type:gv('bt'),ac:!!(bt&&bt.ac),seats:Number(gv('bs')),status:'PENDING_APPROVAL',insExp:gv('bx'),layout:gv('bl'),added:new Date().toISOString(),amen,decks:/Sleeper/.test(gv('bl'))?2:1,ladies:[]});
DB.submissions.unshift({id:uid('SUB'),operatorId:o.id,operator:o.name,type:'BUS',bus:reg,status:'PENDING',submittedAt:new Date().toISOString(),docs:DB.docTypes.filter(d=>d.applies==='BUS'&&d.active&&S.busDocs[d.key]).map(d=>({key:d.key,name:d.name,file:S.busDocs[d.key],status:'PENDING',reason:'',expiry:d.expires?gv('bx'):''})),answers:[],history:[['Submitted',new Date().toISOString()]]});o.buses=myBuses().length;audit('Added bus '+reg,reg);closeModal();render();toast('Sent to Abra for approval')}
else{const b=byId(DB.buses,v);Object.assign(b,{name:gv('bn'),type:gv('bt'),seats:Number(gv('bs')),layout:gv('bl'),insExp:gv('bx'),amen});audit('Edited bus',b.reg);closeModal();render();toast('Saved')}};
A.bus_edit=v=>openModal({t:'Edit bus',w:'wide',b:busForm(byId(DB.buses,v)),f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="bus_save" data-v="${v}">Save</button>`});
A.bus_open=v=>{const b=byId(DB.buses,v),s=busSub(b),nx=myTrips().filter(t=>t.busId===v&&new Date(t.depart)>NOW&&t.status!=='CANCELLED');
openModal({t:b.reg+' · '+b.name,w:'wide',b:`<div class="row rw">${chip(b.status)} ${chip(b.type,'b')} <span class="m">${b.seats} seats · ${esc(b.layout)}</span></div>
${s&&s.status==='REJECTED'?hb('Abra asked for corrections on this bus.','r','alert'):''}${b.status==='PENDING_APPROVAL'?hb('Waiting for Abra approval. You cannot schedule trips on it yet.','a','clock'):''}
<div class="g2"><div>${kvl({'Insurance valid till':fd(b.insExp),Amenities:esc((b.amen||[]).join(', ')||'-'),'Upcoming trips':nx.length,Added:fd(b.added)})}</div><div><b class="sm">Documents</b>${s?s.docs.map((d,i)=>`<div class="row bt doc mt2"><span class="sm">${esc(d.name)}${d.reason?`<div class="sm" style="color:var(--rtx)">${esc(d.reason)}</div>`:''}</span>${d.status==='REJECTED'&&!d.fixed?`<button class="cta sm" data-a="bd_fix" data-v="${s.id}|${i}">Replace</button>`:chip(d.fixed?'Replaced':d.status,d.fixed?'b':'')}</div>`).join('')+(s.status==='REJECTED'&&s.docs.some(d=>d.fixed)&&!s.docs.some(d=>d.status==='REJECTED'&&!d.fixed)?`<button class="cta ok sm mt2" data-a="bd_resend" data-v="${s.id}">Send corrections</button>`:''):'<p class="sm m">Verified by Abra.</p>'}</div></div>`,
f:`<button class="cta gh" data-a="mdl_x">Close</button>${btn('go','layouts|'+v,'Seat layout','grid','gh')}${btn('bus_edit',v,'Edit','edit','gh','buses')}${b.status==='ACTIVE'?btn('bus_mt',v,'Mark maintenance','alert','gh','buses'):b.status==='MAINTENANCE'?btn('bus_mt',v,'Return to service','check','gh','buses'):''}`})};
A.bus_mt=v=>{const b=byId(DB.buses,v);if(b.status==='ACTIVE'){const n=myTrips().filter(t=>t.busId===v&&new Date(t.depart)>NOW&&!['CANCELLED','DRAFT'].includes(t.status)).length;if(n)return toast(n+' upcoming trip(s) use this bus. Move them to another bus first.')}b.status=b.status==='ACTIVE'?'MAINTENANCE':'ACTIVE';audit('Changed bus status',b.reg);closeModal();render();toast('Bus is now '+lab(b.status).toLowerCase())};
A.bd_fix=v=>{const[id,i]=v.split('|'),d=byId(DB.submissions,id).docs[i];closeModal();upDlg('Replace '+d.name,'Reason from Abra: '+esc(d.reason),n=>{d.file=n;d.fixed=true})};
A.bd_resend=v=>{const s=byId(DB.submissions,v);s.docs.forEach(d=>{if(d.fixed){d.status='PENDING';d.reason='';delete d.fixed}});s.status='PENDING';s.history.push(['Corrections sent',new Date().toISOString()]);closeModal();render();toast('Corrections sent')};
IMPORTS.buses.apply=r=>{const o=ME();DB.buses.unshift({id:uid('BUS'),operatorId:o.id,operator:o.name,reg:r[0],name:r[1],type:r[2],ac:/AC/.test(r[2]),seats:Number(r[3]),status:'PENDING_APPROVAL',insExp:new Date(NOW+200*DAY).toISOString().slice(0,10),layout:'2+2 Seater',added:new Date().toISOString(),amen:[],decks:1,ladies:[]})};

/* ---------- SEAT LAYOUT EDITOR ---------- */
function defMap(b){const sl=/Sleeper/.test(b.layout),cols=sl?['S','S','_','S']:['S','S','_','S','S'],rows=Math.ceil(b.seats/(sl?3:4));return Array.from({length:rows},()=>cols.join(''))}
reg('layouts','Seat layouts','grid',v=>{const L=myBuses().filter(b=>b.status!=='RETIRED'),b=byId(DB.buses,v||S.ui.lay)||L[0];if(!b)return`<div class="page">${ph('Seat layouts','')}${empty('No buses yet','Add a bus first.')}</div>`;S.ui.lay=b.id;
const map=S.ui.lmap&&S.ui.lmapBus===b.id?S.ui.lmap:(b.seatMap||defMap(b)),tool=S.ui.ltool||'S',cnt=map.join('').replace(/[^SBL]/g,'').length;
const cell=(c,y,x)=>`<button class="sc t${c}" data-a="lcell" data-v="${y}|${x}" aria-label="${c==='_'?'Aisle':c==='.'?'Empty':c==='B'?'Sleeper berth':c==='L'?'Ladies seat':'Seat'}">${c==='S'?ic('grid',14):c==='B'?'━':c==='L'?'♀':''}</button>`;
return`<div class="page">${ph('Seat layouts','Draw the real seat map. Customers pick seats from this map.',`<div class="fd" style="min-width:220px"><label for="f_lb">Bus</label><select id="f_lb" data-ch="lay_bus">${L.map(x=>`<option value="${x.id}" ${x.id===b.id?'selected':''}>${esc(x.reg)} · ${esc(x.layout)}</option>`).join('')}</select></div>`,[['Fleet'],['Seat layouts']])}
<div class="g21"><div class="c"><div class="row rw">${[['S','Seat'],['B','Sleeper'],['L','Ladies seat'],['_','Aisle'],['.','Empty']].map(([k,l])=>`<button class="ch ${tool===k?'on':''}" data-a="ltool" data-v="${k}"><span class="sc mini t${k}"></span>${l}</button>`).join('')}</div>
<p class="sm m mt2">Choose a type, then click cells. Front of the bus is at the top.</p><div class="sedit">${map.map((r,y)=>`<div class="srow">${[...r].map((c,x)=>cell(c,y,x)).join('')}</div>`).join('')}</div>
<div class="row mt2">${sbtn('lrow','+','Add row','plus')}${sbtn('lrow','-','Remove row','x')}${sbtn('lreset',b.id,'Reset','refresh')}</div></div>
<div class="c"><h3>Summary</h3>${kvl({Bus:esc(b.reg),'Seats in the map':cnt,'Seats on record':b.seats,'Ladies seats':map.join('').replace(/[^L]/g,'').length,'Rows':map.length})}${cnt!==b.seats?hb('The map has '+cnt+' seats, the bus record says '+b.seats+'. Saving updates the bus to '+cnt+' seats.','a','info'):''}<div class="row">${btn('lsave',b.id,'Save layout','check','','layouts')}</div></div></div></div>`});
const curMap=()=>{const b=byId(DB.buses,S.ui.lay);if(!(S.ui.lmap&&S.ui.lmapBus===b.id)){S.ui.lmap=(b.seatMap||defMap(b)).slice();S.ui.lmapBus=b.id}return S.ui.lmap};
A.lay_bus=v=>{S.ui.lay=v;S.ui.lmap=null;navigate('layouts',v)};A.ltool=v=>{S.ui.ltool=v;render()};
A.lcell=v=>{const[y,x]=v.split('|').map(Number),m=curMap(),r=[...m[y]];r[x]=S.ui.ltool||'S';m[y]=r.join('');render()};
A.lrow=v=>{const m=curMap();if(v==='+')m.push(m[m.length-1]||'SS_SS');else if(m.length>1)m.pop();render()};
A.lreset=v=>{S.ui.lmap=defMap(byId(DB.buses,v));S.ui.lmapBus=v;render()};
A.lsave=v=>{const b=byId(DB.buses,v),m=curMap(),n=m.join('').replace(/[^SBL]/g,'').length;b.seatMap=m.slice();b.seats=n;b.ladies=[];audit('Saved seat layout',b.reg);render();toast('Layout saved: '+n+' seats')};

/* ---------- DRIVERS AND CREW ---------- */
reg('crew','Drivers and crew','users',()=>{const L=myCrew(),wk=t=>myTrips().filter(x=>x.driver===t.name&&new Date(x.depart)>NOW&&new Date(x.depart)-NOW<7*DAY&&x.status!=='CANCELLED').length;
return`<div class="page">${ph('Drivers and crew','Drivers sign in to the driver app with their phone number.',btn('cr_new','','Add person','plus','','crew'),[['Fleet'],['Drivers and crew']])}
<div class="kg">${kc('users',L.filter(s=>s.role==='DRIVER').length,'Drivers','')}${kc('check',L.filter(s=>s.status==='ACTIVE').length,'Active','')}${kc('clock',L.filter(s=>s.status==='ON_LEAVE').length,'On leave','')}${kc('file',L.filter(s=>s.licExp&&new Date(s.licExp)-NOW<30*DAY).length,'Licences expiring in 30 days','')}</div>
${tbl('ccrew',[{k:'name',l:'Name',r:x=>`<b>${esc(x.name)}</b><div class="sm m">${esc(x.phone)}</div>`},{k:'role',l:'Role',r:x=>chip(x.role,'b')},{k:'licence',l:'Licence',r:x=>x.licence?esc(x.licence)+(x.licExp?`<div class="sm ${new Date(x.licExp)-NOW<30*DAY?'d dn':'m'}">till ${fd(x.licExp)}</div>`:''):'-'},{k:'wk',l:'Trips in 7 days',v:wk,r:wk},{k:'status',l:'Status',r:x=>chip(x.status)}],L,{filters:[{k:'role',l:'Role',opts:['DRIVER','CONDUCTOR','MANAGER']},{k:'status',l:'Status',opts:['ACTIVE','ON_LEAVE','INACTIVE']}],exp:'crew',emptyT:'No crew yet',emptyS:'Add drivers so you can assign them to trips.'})}</div>`});
function crForm(s){s=s||{name:'',role:'DRIVER',phone:'',licence:'',licExp:'',status:'ACTIVE'};return`<div class="fgrid">${fld('sn','Full name',s.name,{req:1})}${fld('sr','Role',s.role,{type:'select',opts:[['DRIVER','Driver'],['CONDUCTOR','Conductor'],['MANAGER','Manager']]})}${fld('sp','Phone',s.phone,{req:1,ph:'+91 98xxx xxxxx'})}${fld('ss','Status',s.status,{type:'select',opts:[['ACTIVE','Active'],['ON_LEAVE','On leave'],['INACTIVE','Inactive']]})}${fld('sl','Driving licence number',s.licence,{h:'Drivers only'})}${fld('sx','Licence valid till',s.licExp,{type:'date'})}</div>`}
A.cr_new=()=>openModal({t:'Add person',b:crForm(),f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="cr_save">Add</button>`});
A.rec_edit_ops=v=>openModal({t:'Edit',b:crForm(byId(DB.opStaff,v)),f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="cr_save" data-v="${v}">Save</button>`});
A.cr_save=v=>{if(!chk([['sn','Name'],['sp','Phone',x=>x.replace(/\D/g,'').length<10?'Enter a 10 digit number':'']]))return;if(gv('sr')==='DRIVER'&&!gv('sl'))return setErr('sl','Drivers need a licence number');
const d={name:gv('sn'),role:gv('sr'),phone:gv('sp'),status:gv('ss'),licence:gv('sl'),licExp:gv('sx')};if(v)Object.assign(byId(DB.opStaff,v),d);else{DB.opStaff.push(Object.assign({id:uid('ST'),operatorId:S.op,joined:new Date().toISOString().slice(0,10),pin:'1234'},d));if(d.role==='DRIVER')AbraStore.notify('driver:'+d.name,'Welcome to Abra Driver','Sign in with your phone number. Your trips will appear here.','home')}
audit((v?'Edited ':'Added ')+d.role.toLowerCase()+' '+d.name,v||'');closeModal();render();toast(v?'Saved':d.role==='DRIVER'?'Added. The driver app invitation was sent.':'Added')};

/* ---------- ROUTES AND STOPS ---------- */
reg('routes','Routes and stops','nav',v=>{const L=myRoutes();
if(v&&byId(DB.routes,v)){const r=byId(DB.routes,v);return`<div class="page">${ph(esc(r.name),r.km+' km · about '+r.hours+' h',r.operatorId===S.op?btn('rt_edit',r.id,'Edit','edit','gh','routes'):hb('Shared Abra route. Copy it to change the stops.','b','info')+btn('rt_copy',r.id,'Copy as my route','copy','gh','routes'),[['Network'],['Routes','routes'],[r.name]])}
<div class="g21"><div class="c"><h3>Stops in order</h3><div class="tl">${r.stops.map(s=>`<div class="ev ${s.type==='DROPPING'?'r':s.type==='BOTH'?'a':'g'}"><b>${esc(s.name)}</b> ${chip(s.type==='BOARDING'?'Boarding':s.type==='DROPPING'?'Dropping':'Both',s.type==='DROPPING'?'r':'g')}<div class="sm m">${esc(s.city)} · ${s.offset?'+'+Math.floor(s.offset/60)+'h '+s.offset%60+'m':'Start'}</div></div>`).join('')}</div></div>
<div class="c"><h3>Used by</h3>${kvl({'Your trips':myTrips().filter(t=>t.routeId===r.id).length,'Your fares':DB.fares.filter(f=>f.operatorId===S.op&&f.routeId===r.id).length,'Your schedules':DB.schedules.filter(s=>s.operatorId===S.op&&s.routeId===r.id).length})}${mapBox(r.stops.map((s,i)=>({x:12+i*76/Math.max(1,r.stops.length-1),y:i%2?55:40,l:s.name.split(' ').slice(-2).join(' '),c:s.type==='DROPPING'?'red':'grn'})),{h:200,routes:[r.stops.map((s,i)=>[12+i*76/Math.max(1,r.stops.length-1),i%2?55:40])]})}</div></div></div>`}
return`<div class="page">${ph('Routes and stops','Boarding and dropping points come from Abra\'s list of places. Need a new one? Request it.',btn('rt_new','','New route','plus','','routes')+btn('go','places','Request a place','pin','gh'),[['Network'],['Routes']])}
${tbl('crt',[{k:'name',l:'Route',r:x=>`<b>${esc(x.name)}</b>${x.operatorId===S.op?'':' <span class="sm m">(Abra route)</span>'}`},{k:'km',l:'Distance',r:x=>x.km+' km'},{k:'hours',l:'Duration',r:x=>x.hours+' h'},{k:'stops',l:'Stops',r:x=>x.stops.length,v:x=>x.stops.length},{k:'trips',l:'Your trips',r:x=>myTrips().filter(t=>t.routeId===x.id).length,v:x=>myTrips().filter(t=>t.routeId===x.id).length},{k:'status',l:'Status',r:x=>chip(x.status)}],L,{row:'rt_open',exp:'routes',emptyT:'No routes yet',emptyS:'Create a route with its boarding and dropping points.'})}</div>`});
A.rt_open=v=>navigate('routes',v);
function rtForm(r){const st=S.rtStops;const C=DB.cities.filter(c=>c.active).map(c=>c.name);
return`<div class="fgrid">${fld('rf','From',r.from,{type:'select',opts:C})}${fld('rto','To',r.to,{type:'select',opts:C})}${fld('rk','Distance (km)',r.km,{type:'number',min:10,req:1})}${fld('rh','Duration (hours)',r.hours,{type:'number',min:1,max:48,req:1})}</div>
<h4 class="mt">Stops</h4><div class="col" id="rtst">${st.map((s,i)=>`<div class="row rw doc"><b class="sm">${i+1}</b><select class="grow" data-ch="rt_pl" data-k="${i}" aria-label="Place">${DB.places.filter(p=>p.active).map(p=>`<option value="${p.id}" ${p.id===s.placeId?'selected':''}>${esc(p.city)} · ${esc(p.name)}</option>`).join('')}</select><input type="number" style="width:84px" min="0" value="${s.offset}" data-ch="rt_off" data-k="${i}" aria-label="Minutes after start"><select data-ch="rt_ty" data-k="${i}" aria-label="Type">${[['BOARDING','Boarding'],['DROPPING','Dropping'],['BOTH','Both']].map(([k,l])=>`<option value="${k}" ${s.type===k?'selected':''}>${l}</option>`).join('')}</select>${sbtn('rt_mv',i+'|-1','','chevL')}${sbtn('rt_mv',i+'|1','','chevR')}${sbtn('rt_rm',i,'','x')}</div>`).join('')}</div>
<div class="row mt2">${sbtn('rt_add','','Add stop','plus')}<span class="sm m">Minutes = time after departure. Need a place that is not listed? Use Request a place.</span></div>`}
const rtModal=(r,v)=>openModal({t:v?'Edit route':'New route',w:'wide',nofocus:1,b:rtForm(r),f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="rt_save" data-v="${v||''}">Save route</button>`});
const rtKeep=()=>{S.rtDraft={from:gv('rf'),to:gv('rto'),km:gv('rk'),hours:gv('rh')}};
A.rt_new=()=>{const c=DB.cities[0].name,c2=DB.cities[1].name;S.rtStops=[{placeId:DB.places.find(p=>p.city===c).id,offset:0,type:'BOARDING'},{placeId:DB.places.find(p=>p.city===c2).id,offset:600,type:'DROPPING'}];S.rtDraft={from:c,to:c2,km:570,hours:10};S.rtEdit=null;rtModal(S.rtDraft)};
A.rt_edit=v=>{const r=byId(DB.routes,v);S.rtStops=r.stops.map(s=>({...s}));S.rtDraft={from:r.from,to:r.to,km:r.km,hours:r.hours};S.rtEdit=v;rtModal(S.rtDraft,v)};
A.rt_copy=v=>{const r=byId(DB.routes,v);DB.routes.push({...JSON.parse(JSON.stringify(r)),id:uid('RT'),operatorId:S.op,name:r.name+' (mine)'});audit('Copied route',r.name);render();toast('Copied. Edit the stops in your copy.')};
const rtRe=()=>{rtKeep();rtModal(S.rtDraft,S.rtEdit)};
A.rt_add=()=>{const last=S.rtStops[S.rtStops.length-1];S.rtStops.push({placeId:DB.places[0].id,offset:(last?Number(last.offset):0)+60,type:'BOTH'});rtRe()};
A.rt_rm=v=>{if(S.rtStops.length<=2)return toast('A route needs at least 2 stops');S.rtStops.splice(Number(v),1);rtRe()};
A.rt_mv=v=>{const[i,d]=v.split('|').map(Number),j=i+d;if(j<0||j>=S.rtStops.length)return;[S.rtStops[i],S.rtStops[j]]=[S.rtStops[j],S.rtStops[i]];rtRe()};
A.rt_pl=(v,el)=>{S.rtStops[el.dataset.k].placeId=v};A.rt_off=(v,el)=>{S.rtStops[el.dataset.k].offset=Number(v)};A.rt_ty=(v,el)=>{S.rtStops[el.dataset.k].type=v};
A.rt_save=v=>{if(!chk([['rk','Distance',x=>Number(x)>0?'':'Enter the distance'],['rh','Duration',x=>Number(x)>0?'':'Enter the duration']]))return;const st=S.rtStops;
if(gv('rf')===gv('rto'))return setErr('rto','From and To must be different');if(!st.some(s=>s.type!=='DROPPING'))return toast('Add at least one boarding point');if(!st.some(s=>s.type!=='BOARDING'))return toast('Add at least one dropping point');
for(let i=1;i<st.length;i++)if(Number(st[i].offset)<Number(st[i-1].offset))return toast('Stop '+(i+1)+' is earlier than the stop before it');
const stops=st.map(s=>{const p=byId(DB.places,s.placeId);return{placeId:p.id,name:p.name,city:p.city,offset:Number(s.offset),type:s.type}});
const d={from:gv('rf'),to:gv('rto'),name:gv('rf')+' to '+gv('rto'),km:Number(gv('rk')),hours:Number(gv('rh')),stops};
if(v)Object.assign(byId(DB.routes,v),d);else DB.routes.push(Object.assign({id:uid('RT'),operatorId:S.op,status:'ACTIVE'},d));audit((v?'Edited':'Created')+' route '+d.name,'');closeModal();render();toast('Route saved')};

/* ---------- PLACE REQUESTS ---------- */
reg('places','Places','pin',()=>{const o=ME(),L=DB.placeReqs.filter(r=>r.operator===o.name);return`<div class="page">${ph('Places','Abra keeps one list of boarding and dropping points. Ask Abra to add a place you need.',btn('pr_new','','Request a place','plus','','places'),[['Network'],['Places']])}
<div class="c"><h3>Your requests</h3>${tbl('cpr',[{k:'name',l:'Place',r:x=>`<b>${esc(x.name)}</b><div class="sm m">${esc(x.address)}</div>`},{k:'city',l:'City'},{k:'at',l:'Requested',r:x=>rel(x.at),v:x=>x.at},{k:'status',l:'Status',r:x=>chip(x.status)+(x.reason?`<div class="sm" style="color:var(--rtx)">${esc(x.reason)}</div>`:'')}],L,{noq:1,exp:false,emptyT:'No requests',emptyS:'Requests you send to Abra appear here with their status.'})}</div>
<div class="c"><h3>Places you can use</h3>${tbl('cpl',[{k:'name',l:'Place'},{k:'city',l:'City'},{k:'type',l:'Used for',r:x=>chip(x.type,'b')},{k:'landmark',l:'Landmark'}],DB.places.filter(p=>p.active),{filters:[{k:'city',l:'City',opts:DB.cities.map(c=>c.name)}],nocrud:1,exp:'places'})}</div></div>`});
A.pr_new=()=>openModal({t:'Request a place',b:`<div class="fgrid">${fld('pc','City',DB.cities[0].name,{type:'select',opts:DB.cities.filter(c=>c.active).map(c=>c.name)})}${fld('pn','Place name',' ',{req:1,ph:'Miyapur Metro Pickup'})}${fld('pa','Address',' ',{req:1,full:1})}${fld('pl','Landmark','',{full:1})}</div>${hb('Abra checks it is not too close to an existing point, then adds it for every operator.','b','info')}`,f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="pr_save">Send request</button>`});
A.pr_save=()=>{if(!chk([['pn','Place name',x=>DB.places.some(p=>p.name.toLowerCase()===x.toLowerCase()&&p.city===gv('pc'))?'This place already exists':''],['pa','Address']]))return;DB.placeReqs.unshift({id:uid('PR'),operator:ME().name,city:gv('pc'),name:gv('pn').trim(),address:gv('pa').trim(),status:'PENDING',at:new Date().toISOString(),reason:''});audit('Requested place '+gv('pn'),'');closeModal();render();toast('Sent to Abra')};

/* ---------- FARES ---------- */
reg('fares','Fares','tag',()=>{const L=DB.fares.filter(f=>f.operatorId===S.op);return`<div class="page">${ph('Fares','Your fare per seat. Customers pay your fare plus Abra commission, GST and a convenience fee.',btn('fr_new','','New fare','plus','','fares'),[['Sales setup'],['Fares']])}
${tbl('cfr',[{k:'route',l:'Route'},{k:'seatType',l:'Seat type'},{k:'weekday',l:'Weekday',r:x=>money(x.weekday),v:x=>x.weekday},{k:'weekend',l:'Weekend',r:x=>money(x.weekend),v:x=>x.weekend},{k:'festival',l:'Festival',r:x=>money(x.festival),v:x=>x.festival},{k:'cust',l:'Customer pays (weekday)',r:x=>`<b>${money(price(x.weekday,x.route,x.seatType).total)}</b>`,v:x=>x.weekday},{k:'status',l:'Status',r:x=>chip(x.status)}],L,{filters:[{k:'status',l:'Status',opts:['ACTIVE','INACTIVE']}],exp:'fares',emptyT:'No fares yet'})}</div>`});
function frForm(f){f=f||{routeId:(myRoutes()[0]||{}).id,seatType:DB.busTypes[0].name,weekday:100000,weekend:110000,festival:125000,from:new Date().toISOString().slice(0,10),status:'ACTIVE'};return`<div class="fgrid">${fld('fr','Route',f.routeId,{type:'select',opts:myRoutes().map(r=>[r.id,r.name])})}${fld('ft','Seat type',f.seatType,{type:'select',opts:DB.busTypes.filter(t=>t.active).map(t=>t.name)})}${fld('fw','Weekday fare (Rs)',f.weekday/100,{type:'number',min:1,req:1})}${fld('fe','Weekend fare (Rs)',f.weekend/100,{type:'number',min:1,req:1})}${fld('ff','Festival fare (Rs)',f.festival/100,{type:'number',min:1,req:1})}${fld('fd','Effective from',f.from,{type:'date',req:1})}${fld('fs','Status',f.status,{type:'select',opts:['ACTIVE','INACTIVE']})}</div><div id="fprev"></div>`}
function frPrev(){const e=$('#fprev');if(!e)return;const r=byId(DB.routes,gv('fr')),p=price(Number(gv('fw'))*100||0,r?r.name:'',gv('ft'));e.innerHTML=`<div class="xcard"><b>What the customer pays on a weekday</b><div class="xstat mt2"><div><span class="sm m">Your fare</span><b>${money(p.fare)}</b></div><div><span class="sm m">Abra commission</span><b>${money(p.cm)}</b></div><div><span class="sm m">GST (5%)</span><b>${money(p.gst)}</b></div><div><span class="sm m">Convenience fee</span><b>${money(p.fee)}</b></div><div><span class="sm m">Customer pays</span><b>${money(p.total)}</b></div></div><p class="sm m mt2">Commission rule: ${esc(ruleTxt(p.rule))}. You receive ${money(p.fare)} per seat.</p></div>`}
const frModal=(t,f,v)=>{openModal({t,w:'wide',b:frForm(f),f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="fr_save" data-v="${v||''}">Save fare</button>`});frPrev();$$('#modalRoot input,#modalRoot select').forEach(e=>e.addEventListener('input',frPrev))};
A.fr_new=()=>{if(!myRoutes().length)return toast('Create a route first');frModal('New fare')};A.fare_edit=v=>frModal('Edit fare',byId(DB.fares,v),v);
A.fr_save=v=>{if(!chk([['fw','Weekday fare',x=>Number(x)<100?'At least Rs 100':''],['fe','Weekend fare',x=>Number(x)<Number(gv('fw'))*.5?'Too low compared with weekday':''],['ff','Festival fare',x=>Number(x)<100?'At least Rs 100':'']]))return;
const r=byId(DB.routes,gv('fr')),d={operatorId:S.op,routeId:r.id,route:r.name,seatType:gv('ft'),weekday:Math.round(gv('fw')*100),weekend:Math.round(gv('fe')*100),festival:Math.round(gv('ff')*100),from:gv('fd'),status:gv('fs')};
const dup=DB.fares.find(f=>f.id!==v&&f.operatorId===S.op&&f.routeId===d.routeId&&f.seatType===d.seatType&&f.status==='ACTIVE');if(dup&&d.status==='ACTIVE')return toast('An active fare already exists for this route and seat type. Edit that one.');
if(v)Object.assign(byId(DB.fares,v),d);else DB.fares.push(Object.assign({id:uid('FR')},d));audit('Saved fare '+d.route,'');closeModal();render();toast('Fare saved')};

/* ---------- SCHEDULES ---------- */
const WD=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
reg('schedules','Schedules','cal',()=>{const L=DB.schedules.filter(s=>s.operatorId===S.op);return`<div class="page">${ph('Schedules','Repeat a trip on chosen days, then create the trips in one go.',btn('sc_new','','New schedule','plus','','schedules'),[['Sales setup'],['Schedules']])}
${tbl('csc',[{k:'route',l:'Route'},{k:'bus',l:'Bus'},{k:'time',l:'Departs'},{k:'days',l:'Days',r:x=>x.days.length===7?'Every day':x.days.join(', ')},{k:'to',l:'Valid till',r:x=>fd(x.to),v:x=>x.to},{k:'status',l:'Status',r:x=>chip(x.status)},{k:'_act',l:'',r:x=>sbtn('sc_gen',x.id,'Create trips','cal','gh','schedules')}],L,{exp:'schedules',emptyT:'No schedules'})}</div>`});
function scForm(s){s=s||{routeId:(myRoutes()[0]||{}).id,busId:(myBuses().find(b=>b.status==='ACTIVE')||{}).id,time:'21:30',days:WD.slice(),from:new Date().toISOString().slice(0,10),to:new Date(NOW+60*DAY).toISOString().slice(0,10),status:'ACTIVE'};S.scDays=s.days.slice();
return`<div class="fgrid">${fld('sr','Route',s.routeId,{type:'select',opts:myRoutes().map(r=>[r.id,r.name])})}${fld('sb','Bus',s.busId,{type:'select',opts:myBuses().filter(b=>b.status==='ACTIVE').map(b=>[b.id,b.reg+' · '+b.type])})}${fld('st','Departure time',s.time,{type:'time',req:1})}${fld('ss','Status',s.status,{type:'select',opts:['ACTIVE','INACTIVE']})}${fld('sf','From',s.from,{type:'date',req:1})}${fld('su','Till',s.to,{type:'date',req:1})}<div class="full"><b class="sm">Days</b><div class="row rw mt2" id="scd">${WD.map(d=>`<button class="ch ${S.scDays.includes(d)?'on':''}" data-a="sc_day" data-v="${d}">${d}</button>`).join('')}</div></div></div>`}
A.sc_day=(v,el)=>{const i=S.scDays.indexOf(v);i<0?S.scDays.push(v):S.scDays.splice(i,1);el.classList.toggle('on')};
A.sc_new=()=>{if(!myRoutes().length||!myBuses().some(b=>b.status==='ACTIVE'))return toast('You need a route and an approved bus first');openModal({t:'New schedule',w:'wide',b:scForm(),f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="sc_save">Save</button>`})};
A.sch_edit=v=>openModal({t:'Edit schedule',w:'wide',b:scForm(byId(DB.schedules,v)),f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="sc_save" data-v="${v}">Save</button>`});
A.sc_save=v=>{if(!S.scDays.length)return toast('Pick at least one day');if(gv('su')<gv('sf'))return setErr('su','Till must be after From');const r=byId(DB.routes,gv('sr')),b=byId(DB.buses,gv('sb')),f=DB.fares.find(x=>x.operatorId===S.op&&x.routeId===r.id&&x.seatType===b.type);
const d={operatorId:S.op,routeId:r.id,route:r.name,busId:b.id,bus:b.reg,time:gv('st'),days:S.scDays.slice(),from:gv('sf'),to:gv('su'),status:gv('ss'),fare:f?f.weekday:100000};if(v)Object.assign(byId(DB.schedules,v),d);else DB.schedules.push(Object.assign({id:uid('SC')},d));audit('Saved schedule '+r.name,'');closeModal();render();toast(f?'Saved':'Saved. Add a fare for this route and seat type, the Rs 1,000 default is used for now.')};
A.sc_gen=v=>{const s=byId(DB.schedules,v),r=byId(DB.routes,s.routeId),b=byId(DB.buses,s.busId);if(s.status!=='ACTIVE')return toast('Activate the schedule first');if(!b||b.status!=='ACTIVE')return toast('The bus is not active');let n=0,skip=0;
for(let k=0;k<14;k++){const d=new Date(NOW+k*DAY),di=(d.getDay()+6)%7;if(!s.days.includes(WD[di]))continue;const ds=d.toISOString().slice(0,10);if(ds<s.from||ds>s.to)continue;const[h,m]=s.time.split(':').map(Number);d.setHours(h,m,0,0);if(d<NOW)continue;
if(DB.trips.some(t=>t.busId===b.id&&sameDay(t.depart,d)&&t.status!=='CANCELLED')){skip++;continue}
const f=DB.fares.find(x=>x.operatorId===S.op&&x.routeId===r.id&&x.seatType===b.type),we=di>=5;
DB.trips.push({id:uid('TRP'),routeId:r.id,route:r.name,operatorId:S.op,operator:ME().name,busId:b.id,bus:b.reg,busName:b.name,type:b.type,depart:d.toISOString(),status:'DRAFT',seats:b.seats,booked:0,held:0,blocked:0,fare:f?(we?f.weekend:f.weekday):s.fare,driver:'',conductor:'',taken:[],checkedIn:[],scheduleId:s.id});n++}
audit('Created '+n+' trips from schedule',v);render();toast(n+' draft trips created'+(skip?', '+skip+' skipped (bus already busy that day)':'')+'. Publish them in Trips.')};

/* ---------- TRIPS ---------- */
reg('trips','Trips','cal',v=>{const L=myTrips();return`<div class="page">${ph('Trips','Publish a trip to put it on sale in the customer app.',btn('tr_new','','New trip','plus','','trips'),[['Sales setup'],['Trips']])}
<div class="kg">${kc('cal',L.filter(t=>new Date(t.depart)>NOW&&t.status==='SCHEDULED').length,'On sale','')}${kc('edit',L.filter(t=>t.status==='DRAFT').length,'Drafts','')}${kc('nav',L.filter(t=>['BOARDING','IN_TRANSIT','DEPARTED','DELAYED'].includes(t.status)).length,'Running now','')}${kc('user',L.filter(t=>new Date(t.depart)>NOW&&t.status!=='CANCELLED'&&!t.driver).length,'Without a driver','')}</div>
${tbl('ctr',[{k:'id',l:'Trip',r:x=>`<b>${x.id}</b><div class="sm m">${esc(x.route)}</div>`,v:x=>x.id},{k:'depart',l:'Departs',r:x=>fdt(x.depart),v:x=>x.depart},{k:'bus',l:'Bus'},{k:'driver',l:'Driver',r:x=>x.driver?esc(x.driver):chip('Not assigned','a')},{k:'booked',l:'Booked',r:x=>`${x.booked}/${x.seats} <div class="bar" style="width:70px"><i style="width:${x.booked/x.seats*100}%"></i></div>`,v:x=>x.booked/x.seats},{k:'fare',l:'Fare',r:x=>money(x.fare),v:x=>x.fare},{k:'status',l:'Status',r:x=>chip(x.status)}],L,{row:'tr_open',sort:'depart',dir:1,filters:[{k:'status',l:'Status',opts:['DRAFT','SCHEDULED','BOARDING','IN_TRANSIT','DELAYED','ARRIVED','CANCELLED']},{k:'when',l:'When',opts:[['up','Upcoming'],['today','Today'],['past','Past']],fn:(x,w)=>w==='up'?new Date(x.depart)>NOW:w==='today'?sameDay(x.depart,NOW):new Date(x.depart)<NOW}],bulk:[{a:'tr_bulk_pub',l:'Publish selected',c:'ok',p:'trips'}],exp:'trips',emptyT:'No trips yet',emptyS:'Create a trip or generate them from a schedule.'})}</div>`});
function trForm(){const B=myBuses().filter(b=>b.status==='ACTIVE');return`<div class="fgrid">${fld('tr','Route',(myRoutes()[0]||{}).id,{type:'select',opts:myRoutes().map(r=>[r.id,r.name])})}${fld('tb','Bus',(B[0]||{}).id,{type:'select',opts:B.map(b=>[b.id,b.reg+' · '+b.type+' · '+b.seats+' seats'])})}${fld('td','Date',new Date(NOW+DAY).toISOString().slice(0,10),{type:'date',req:1})}${fld('tt','Departure time','21:30',{type:'time',req:1})}${fld('tdv','Driver','',{type:'select',opts:[['','Assign later']].concat(myDrivers().map(d=>[d.name,d.name]))})}${fld('tf','Fare per seat (Rs)','',{type:'number',min:100,h:'Empty = your fare for this route and seat type'})}</div><label class="row sm mt2"><input type="checkbox" class="ckb" id="f_tp" checked> Publish now (customers can book at once)</label>`}
A.tr_new=()=>{if(!myRoutes().length)return toast('Create a route first');if(!myBuses().some(b=>b.status==='ACTIVE'))return toast('You need a bus approved by Abra first');openModal({t:'New trip',w:'wide',b:trForm(),f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="tr_save">Create trip</button>`})};
A.tr_save=()=>{const r=byId(DB.routes,gv('tr')),b=byId(DB.buses,gv('tb')),d=new Date(gv('td')+'T'+gv('tt'));if(!gv('td')||isNaN(d))return setErr('td','Pick a date');if(d<NOW)return setErr('td','The departure is in the past');
if(DB.trips.some(t=>t.busId===b.id&&t.status!=='CANCELLED'&&Math.abs(new Date(t.depart)-d)<r.hours*36e5))return setErr('tb','This bus is already on another trip at that time');
const dv=gv('tdv');if(dv){const c=conflict(dv,d);if(c)return setErr('tdv',dv+' already drives '+c.id+' around that time')}
const f=DB.fares.find(x=>x.operatorId===S.op&&x.routeId===r.id&&x.seatType===b.type),we=[0,6].includes(d.getDay()),fare=gv('tf')?Math.round(gv('tf')*100):f?(we?f.weekend:f.weekday):0;if(!fare)return setErr('tf','No fare set for this route and seat type. Enter one.');
const id=uid('TRP');DB.trips.push({id,routeId:r.id,route:r.name,operatorId:S.op,operator:ME().name,busId:b.id,bus:b.reg,busName:b.name,type:b.type,depart:d.toISOString(),status:$('#f_tp').checked?'SCHEDULED':'DRAFT',seats:b.seats,booked:0,held:0,blocked:0,fare,driver:dv,conductor:'',taken:[],checkedIn:[]});audit('Created trip '+id,id);closeModal();render();toast($('#f_tp').checked?'Trip is on sale':'Draft saved')};
A.tr_bulk_pub=v=>{const ids=selIds(v);let n=0;ids.forEach(i=>{const t=byId(DB.trips,i);if(t&&t.status==='DRAFT'){t.status='SCHEDULED';n++}});S.t[v].sel={};audit('Published '+n+' trips','');render();toast(n+' trip(s) published')};
function seatGrid(t){const st=AbraStore.seatStates(t),C={A:'',B:'bk',H:'hd',X:'bl',L:'ld'};let h='';for(let i=0;i<st.length;i++){if(i%4===2)h+='<span class="aisle"></span>';h+=`<span class="seat ${C[st[i]]}" title="${AbraStore.seatLabelFor(t,i)}">${AbraStore.seatLabelFor(t,i)}</span>`;if(i%4===3)h+='<br>'}return`<div class="seatmap">${h}</div><div class="row rw sm mt2"><span class="seat"></span>Free <span class="seat bk"></span>Booked <span class="seat hd"></span>Held <span class="seat bl"></span>Blocked <span class="seat ld"></span>Ladies</div>`}
A.tr_open=v=>{const t=byId(DB.trips,v),r=byId(DB.routes,t.routeId),bk=DB.bookings.filter(b=>b.tripId===v),lv=DB.live.find(l=>l.tripId===v),ci=t.checkedIn||[];
openModal({t:t.id+' · '+t.route,w:'wide',b:`<div class="row rw">${chip(t.status)} <span class="m">${fdt(t.depart)} · ${esc(t.bus)} · ${esc(t.type)} · ${money(t.fare)} per seat</span></div>${t.status==='DELAYED'?hb('Delayed'+(t.delay?' by '+t.delay+' min':'')+(t.delayReason?': '+esc(t.delayReason):''),'a','clock'):''}${lv?hb('Live: '+lv.speed+' km/h, '+lv.progress+'% of the route, last update '+rel(lv.ping),'b','nav'):''}
<div class="g2"><div>${kvl({Driver:t.driver?esc(t.driver):'<span class="st a">Not assigned</span>',Booked:t.booked+' of '+t.seats,'Checked in':ci.length+' of '+bk.filter(b=>b.status!=='CANCELLED').length+' bookings','Boarding from':r&&r.stops?esc(r.stops.filter(s=>s.type!=='DROPPING').map(s=>s.name).join(', ')):'-'})}</div><div>${seatGrid(t)}</div></div>
<h4 class="mt">Passenger list (${bk.length})</h4>${bk.length?`<div class="tw"><table class="dt" style="min-width:0"><thead><tr><th>PNR</th><th>Passenger</th><th>Seats</th><th>Phone</th><th>Status</th></tr></thead><tbody>${bk.map(b=>`<tr><td>${esc(b.pnr)}</td><td>${esc(b.customer)}</td><td>${esc(b.seatList)}</td><td>${esc(b.phone.slice(0,6))}•••••${esc(b.phone.slice(-3))}</td><td>${chip(b.status)} ${ci.includes(b.id)?chip('Checked in','g'):''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="m sm">No bookings yet.</p>'}`,
f:`<button class="cta gh" data-a="mdl_x">Close</button>${bk.length?btn('tr_man',v,'Download manifest','download','gh'):''}${t.status==='DRAFT'?btn('tr_pub',v,'Publish','check','ok','trips'):''}${!['CANCELLED','ARRIVED'].includes(t.status)?btn('tr_drv',v,'Driver','user','gh','trips')+btn('tr_delay',v,'Delay','clock','gh','trips')+btn('tr_cancel',v,'Cancel trip','x','dg','trips'):''}`})};
A.tr_pub=v=>{byId(DB.trips,v).status='SCHEDULED';audit('Published trip',v);closeModal();render();toast('Published. Customers can book it now.')};
A.tr_man=v=>{const t=byId(DB.trips,v);csv('manifest_'+v,[{label:'PNR',x:b=>b.pnr},{label:'Passenger',x:b=>b.customer},{label:'Seats',x:b=>b.seatList},{label:'Phone',x:b=>b.phone},{label:'Status',x:b=>b.status},{label:'Checked in',x:b=>(t.checkedIn||[]).includes(b.id)?'Yes':'No'}],DB.bookings.filter(b=>b.tripId===v))};
A.tr_drv=v=>{const t=byId(DB.trips,v);openModal({t:'Driver for '+v,w:'sm2',b:`${fld('dv','Driver',t.driver,{type:'select',opts:[['','Not assigned']].concat(myDrivers().map(d=>{const c=conflict(d.name,t.depart,v);return[d.name,d.name+(c?' (busy: '+c.id+')':'')]}))})}<p class="sm m">The driver gets the trip in the driver app at once.</p>`,f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="tr_drv_ok" data-v="${v}">Save</button>`})};
A.tr_drv_ok=v=>{const t=byId(DB.trips,v),d=gv('dv');if(d){const c=conflict(d,t.depart,v);if(c)return setErr('dv',d+' already drives '+c.id+' around that time')}t.driver=d;audit('Assigned driver '+(d||'none'),v);closeModal();render();toast(d?d+' assigned':'Driver removed')};
A.tr_delay=v=>openModal({t:'Delay '+v,w:'sm2',b:`<div class="fgrid">${fld('dm','Delay (minutes)',30,{type:'number',min:5,max:720,req:1,full:1})}${fld('dr','Reason (customers see it)','',{req:1,full:1,ph:'Heavy traffic at the start point'})}</div>`,f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="tr_delay_ok" data-v="${v}">Delay and notify</button>`});
A.tr_delay_ok=v=>{if(!chk([['dm','Minutes',x=>Number(x)>=5&&Number(x)<=720?'':'Enter 5 to 720'],['dr','Reason']]))return;const t=byId(DB.trips,v);t.status='DELAYED';t.delay=Number(gv('dm'));t.delayReason=gv('dr');audit('Delayed trip',v);closeModal();render();toast('Delayed. Passengers and Abra were notified.')};
A.tr_cancel=v=>{const t=byId(DB.trips,v),n=DB.bookings.filter(b=>b.tripId===v&&b.status==='CONFIRMED').length;openModal({t:'Cancel '+v,w:'sm2',b:`${hb(n+' booking(s) get a full refund. You bear the refund because you cancelled.','r','alert')}${fld('cr','Reason','',{req:1,full:1})}`,f:`<button class="cta gh" data-a="mdl_x">Keep trip</button><button class="cta dg" data-a="tr_cancel_ok" data-v="${v}">Cancel trip and refund</button>`})};
A.tr_cancel_ok=v=>{if(!chk([['cr','Reason']]))return;const t=byId(DB.trips,v);t.status='CANCELLED';DB.bookings.filter(b=>b.tripId===v&&b.status==='CONFIRMED').forEach(b=>{b.status='CANCELLED';DB.refunds.unshift({id:uid('RF'),bookingId:b.id,pnr:b.pnr,customer:b.customer,operator:b.operator,amount:b.amount,pct:100,status:'INITIATED',utr:'',at:new Date().toISOString(),bearer:'Operator',reason:'Trip cancelled by operator: '+gv('cr')})});audit('Cancelled trip',v);closeModal();render();toast('Cancelled. Refunds started, passengers notified.')};

/* ---------- BOOKINGS ---------- */
reg('bookings','Bookings','ticket',()=>{const L=myBk();return`<div class="page">${ph('Bookings','Bookings on your trips from the Abra customer app.','',[['Sales'],['Bookings']])}
<div class="kg">${kc('ticket',L.length,'Bookings','')}${kc('check',L.filter(b=>b.status==='CONFIRMED').length,'Confirmed','')}${kc('x',L.filter(b=>b.status==='CANCELLED').length,'Cancelled','')}${kc('wallet',inrs(L.filter(b=>b.status!=='CANCELLED').reduce((a,b)=>a+b.amount-b.commission,0)),'Your share','')}</div>
${tbl('cbk',[{k:'pnr',l:'PNR',r:x=>`<b>${esc(x.pnr)}</b>`},{k:'customer',l:'Passenger'},{k:'route',l:'Route',r:x=>`${esc(x.route)}<div class="sm m">${x.tripId}</div>`},{k:'travelDate',l:'Travel',r:x=>fdt(x.travelDate),v:x=>x.travelDate},{k:'seatList',l:'Seats'},{k:'amount',l:'Fare',r:x=>money(x.amount),v:x=>x.amount},{k:'share',l:'You get',r:x=>money(x.amount-x.commission),v:x=>x.amount-x.commission},{k:'status',l:'Status',r:x=>chip(x.status)}],L,{row:'cb_open',sort:'travelDate',dir:-1,filters:[{k:'status',l:'Status',opts:['CONFIRMED','COMPLETED','CANCELLED']},{k:'route',l:'Route',opts:[...new Set(L.map(b=>b.route))]}],exp:'bookings',emptyT:'No bookings yet'})}</div>`});
A.cb_open=v=>{const b=byId(DB.bookings,v),t=byId(DB.trips,b.tripId),rf=DB.refunds.find(r=>r.bookingId===v);openModal({t:b.pnr,b:`${kvl({Passenger:esc(b.customer),Phone:esc(b.phone),Trip:b.tripId+' · '+esc(b.route),Travel:fdt(b.travelDate),Seats:esc(b.seatList),'Fare paid':money(b.amount),'Abra commission':money(b.commission),'You get':money(b.amount-b.commission),'Paid by':esc(b.mode),Status:chip(b.status),'Checked in':t&&(t.checkedIn||[]).includes(b.id)?'Yes':'No'})}${rf?hb('Refund '+rf.id+': '+money(rf.amount)+', '+lab(rf.status).toLowerCase()+', paid by '+rf.bearer,'b','refresh'):''}`,f:`<button class="cta gh" data-a="mdl_x">Close</button>${btn('tel',b.customer,'Call passenger','phone','gh')}${b.status==='CONFIRMED'&&t&&new Date(t.depart)>NOW?btn('cb_cancel',v,'Cancel booking','x','dg','bookings'):''}`})};
A.cb_cancel=v=>{const b=byId(DB.bookings,v);confirmD({t:'Cancel '+b.pnr,msg:'The passenger gets a full refund of '+money(b.amount)+'. You bear it.',ok:'Cancel booking',tone:'dg',run:()=>{b.status='CANCELLED';const t=byId(DB.trips,b.tripId);if(t){t.booked=Math.max(0,t.booked-b.seatsN);t.taken=(t.taken||[]).filter(s=>!b.seatList.split(', ').includes(s))}DB.refunds.unshift({id:uid('RF'),bookingId:b.id,pnr:b.pnr,customer:b.customer,operator:b.operator,amount:b.amount,pct:100,status:'INITIATED',utr:'',at:new Date().toISOString(),bearer:'Operator',reason:'Cancelled by operator'});audit('Cancelled booking',b.pnr);render();toast('Cancelled and refund started')}})};

/* ---------- OFFERS ---------- */
reg('offers','Offers','tag',()=>{const o=ME(),L=DB.offers.filter(f=>f.funder==='OPERATOR'&&String(f.scope).includes(o.name));return`<div class="page">${ph('Offers','Discounts you pay for, shown to customers on your buses. Abra approves each one.',btn('of_req','','Request an offer','plus','','offers'),[['Sales'],['Offers']])}
${tbl('cof',[{k:'code',l:'Code',r:x=>`<b>${esc(x.code)}</b><div class="sm m">${esc(x.desc)}</div>`},{k:'value',l:'Discount',r:x=>x.type==='PERCENT'?x.value/100+'% up to '+money(x.maxDisc):money(x.value)},{k:'to',l:'Valid till',r:x=>fd(x.to),v:x=>x.to},{k:'used',l:'Used',r:x=>x.used+(x.limit?' / '+x.limit:'')},{k:'cost',l:'Cost to you',r:x=>money(x.used*(x.type==='PERCENT'?Math.min(x.maxDisc,x.value*10):x.value)),v:x=>x.used},{k:'status',l:'Status',r:x=>chip(x.status==='DRAFT'?'PENDING':x.status)}],L,{exp:'offers',emptyT:'No offers yet',emptyS:'Request an offer to fill empty seats.'})}</div>`});
A.of_req=()=>openModal({t:'Request an offer',b:`<div class="fgrid">${fld('oc','Code','',{req:1,ph:'KAVERI10'})}${fld('ot','Type','FLAT',{type:'select',opts:[['FLAT','Flat amount'],['PERCENT','Percentage']]})}${fld('ov','Value (Rs, or percent)','',{type:'number',min:1,req:1})}${fld('om','Maximum discount (Rs)','',{type:'number',min:0})}${fld('ou','Valid till',new Date(NOW+30*DAY).toISOString().slice(0,10),{type:'date',req:1})}${fld('ol','Total uses (0 = no limit)',500,{type:'number',min:0})}${fld('od','Description (customers see it)','',{req:1,full:1})}</div>${hb('You pay the discount. Abra checks the terms and switches it on.','b','info')}`,f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="of_req_ok">Send to Abra</button>`});
A.of_req_ok=()=>{if(!chk([['oc','Code',x=>/^[A-Z0-9]{4,12}$/i.test(x)?(DB.offers.some(f=>f.code.toUpperCase()===x.toUpperCase())?'This code is taken':''):'4 to 12 letters or numbers'],['ov','Value',x=>Number(x)>0?(gv('ot')==='PERCENT'&&Number(x)>50?'At most 50%':''):'Enter a value'],['od','Description']]))return;const pc=gv('ot')==='PERCENT';
DB.offers.unshift({id:uid('OF'),code:gv('oc').toUpperCase(),desc:gv('od'),type:gv('ot'),value:pc?Math.round(gv('ov')*100):Math.round(gv('ov')*100),maxDisc:Math.round((Number(gv('om'))||Number(gv('ov')))*100),minAmt:0,status:'DRAFT',funder:'OPERATOR',perUser:1,limit:Number(gv('ol')),used:0,from:new Date().toISOString().slice(0,10),to:gv('ou'),scope:'Operator: '+ME().name,newOnly:false,terms:['Valid on '+ME().name+' buses only.']});audit('Requested offer '+gv('oc'),'');closeModal();render();toast('Sent to Abra for approval')};

/* ---------- EARNINGS AND SETTLEMENTS ---------- */
reg('earnings','Earnings and settlements','wallet',()=>{const o=ME(),L=DB.settlements.filter(s=>s.operatorId===S.op),B=myBk().filter(b=>(NOW-new Date(b.at))/DAY<=30),G=B.filter(b=>b.status!=='CANCELLED').reduce((a,b)=>a+b.amount,0),C=B.filter(b=>b.status!=='CANCELLED').reduce((a,b)=>a+b.commission,0),RF=DB.refunds.filter(r=>r.operator===o.name&&r.bearer==='Operator').reduce((a,r)=>a+r.amount,0);
return`<div class="page">${ph('Earnings and settlements','Abra collects the payment, keeps its commission and pays you every cycle.','',[['Money'],['Earnings']])}
<div class="kg">${kc('wallet',inrs(G),'Gross sales, 30 days','')}${kc('percent',inrs(C),'Abra commission','')}${kc('refresh',inrs(RF),'Refunds you bore','')}${kc('check',inrs(G-C-RF),'Your net, 30 days','')}</div>
<div class="c row bt rw"><span>Payout: <b>${o.payout==='AUTO'?'Automatic (Razorpay Route)':'Manual, every '+DB.payoutCfg.cycleDays+' days'}</b> · Bank ${chip(o.bank.status)}</span>${btn('go','company','Bank details','wallet','gh')}</div>
${tbl('cst',[{k:'id',l:'Settlement',r:x=>`<b>${x.id}</b><div class="sm m">${esc(x.cycle)}</div>`},{k:'gross',l:'Gross',r:x=>money(x.gross),v:x=>x.gross},{k:'commission',l:'Commission',r:x=>money(x.commission),v:x=>x.commission},{k:'refunds',l:'Refunds',r:x=>money(x.refunds),v:x=>x.refunds},{k:'net',l:'Net payable',r:x=>`<b>${money(x.net)}</b>`,v:x=>x.net},{k:'status',l:'Status',r:x=>chip(x.status)+(x.query?' '+chip('Query open','a'):'')}],L,{row:'cs_open',exp:'settlements',emptyT:'No settlements yet'})}</div>`});
A.cs_open=v=>{const s=byId(DB.settlements,v);openModal({t:s.id+' · '+s.cycle,b:`${kvl({Gross:money(s.gross),'Abra commission':'- '+money(s.commission),Refunds:'- '+money(s.refunds),Adjustments:money(s.adj),'Net payable':'<b>'+money(s.net)+'</b>',Status:chip(s.status),'Paid on':s.paidAt?fdt(s.paidAt):'-'})}${s.query?hb('Your query: '+esc(s.query)+' (waiting for Abra)','a','help'):''}`,f:`<button class="cta gh" data-a="mdl_x">Close</button>${btn('cs_stmt',v,'Download statement','download','gh')}${s.query||s.status==='PAID'?'':btn('cs_q',v,'Raise a query','help','','earnings')}`})};
A.cs_stmt=v=>{const s=byId(DB.settlements,v);csv('statement_'+v,[{label:'PNR',x:b=>b.pnr},{label:'Route',x:b=>b.route},{label:'Fare (INR)',x:b=>b.amount/100},{label:'Commission (INR)',x:b=>b.commission/100},{label:'You get (INR)',x:b=>(b.amount-b.commission)/100},{label:'Status',x:b=>b.status}],myBk().slice(0,s.lines>40?40:s.lines))};
A.cs_q=v=>openModal({t:'Raise a query on '+v,w:'sm2',b:fld('sq','What looks wrong?','',{type:'textarea',req:1,ph:'2 refunds on 3 Oct were charged to us but the trip was not cancelled by us.'}),f:`<button class="cta gh" data-a="mdl_x">Cancel</button><button class="cta" data-a="cs_q_ok" data-v="${v}">Send to Abra</button>`});
A.cs_q_ok=v=>{if(!chk([['sq','Query',x=>x.length<10?'Explain in a few words':'']]))return;byId(DB.settlements,v).query=gv('sq');audit('Raised settlement query',v);closeModal();render();toast('Sent. Abra will reply here.')};

/* ---------- COMMISSION ---------- */
reg('commission','Commission','percent',()=>{const o=ME(),typ=[...new Set(myBuses().map(b=>b.type))],rts=myRoutes().map(r=>r.name),L=DB.commissions.filter(c=>c.status==='ACTIVE'&&((c.scope==='OPERATOR'&&c.target===o.name)||(c.scope==='ROUTE'&&rts.includes(c.target))||(c.scope==='BUS_TYPE'&&typ.includes(c.target))));const f=Number(S.ui.cf||1000);
const r=myRoutes()[0],p=price(f*100,S.ui.cr||(r?r.name:''),S.ui.ct||typ[0]||'');
return`<div class="page">${ph('Commission','What Abra keeps from each seat. Agreed with Abra, you cannot change it here.','',[['Money'],['Commission']])}
<div class="g2"><div class="c"><h3>Rules that apply to you</h3>${L.length?L.map(c=>`<div class="doc row bt"><span><b>${lab(c.scope)}</b>: ${esc(c.target)}<div class="sm m">${esc(c.note)} · from ${fd(c.from)}</div></span><b>${c.mode==='PERCENT'?c.value/100+'%':money(c.value)+'/seat'}</b></div>`).join(''):''}<div class="doc row bt"><span><b>Default</b><div class="sm m">Used when nothing more specific applies</div></span><b>${DB.commissionDefault.value/100}%</b></div><p class="sm m">The most specific rule wins: your company, then the route, then the bus type, then the default.</p></div>
<div class="c"><h3>Price calculator</h3><div class="fgrid">${fld('cf','Your fare per seat (Rs)',f,{type:'number',min:1})}${fld('cr','Route',S.ui.cr||(r?r.name:''),{type:'select',opts:rts})}${fld('ct','Seat type',S.ui.ct||typ[0]||'',{type:'select',opts:typ})}</div><div class="row">${btn('cm_calc','','Calculate','refresh','gh')}</div>
<div class="xstat mt2"><div><span class="sm m">Commission</span><b>${money(p.cm)}</b></div><div><span class="sm m">GST</span><b>${money(p.gst)}</b></div><div><span class="sm m">Fee</span><b>${money(p.fee)}</b></div><div><span class="sm m">Customer pays</span><b>${money(p.total)}</b></div><div><span class="sm m">You get</span><b>${money(p.fare)}</b></div></div><p class="sm m">Rule used: ${esc(ruleTxt(p.rule))}</p></div></div></div>`});
A.cm_calc=()=>{S.ui.cf=gv('cf');S.ui.cr=gv('cr');S.ui.ct=gv('ct');render()};

