reg('live','Live buses and safety','nav',()=>{const T=myTrips(),L=DB.live.filter(l=>T.some(t=>t.id===l.tripId)),SO=DB.sos.filter(s=>T.some(t=>t.id===s.trip));
return`<div class="page">${ph('Live buses and safety','Where your running buses are, and any SOS from passengers.','',[['Operations'],['Live']])}
${SO.filter(s=>['NEW','ACKNOWLEDGED','RESPONDING'].includes(s.status)).map(s=>hb(`<b>SOS from ${esc(s.customer)}</b> on ${s.trip} (${esc(s.route)}): ${esc(s.note||'needs help')}. Abra's safety team is handling it. Status: ${lab(s.status)}.`,'r','alert')).join('')}
<div class="g21"><div class="c">${mapBox(L.map(l=>({x:l.x,y:l.y,l:l.bus,c:l.state==='LIVE'?'grn':l.state==='DELAYED'?'amb':'red',t:l.route})),{h:360})}</div><div class="c"><h3>Running now (${L.length})</h3>${L.length?L.map(l=>`<div class="doc"><div class="row bt"><b>${esc(l.bus)}</b>${chip(l.state)}</div><div class="sm m">${esc(l.route)} · ${esc(l.driver)}</div><div class="bar mt2"><i style="width:${l.progress}%"></i></div><div class="row bt sm mt2"><span>${l.speed} km/h · ${rel(l.ping)}</span>${sbtn('tel',l.driver,'Call','phone')}</div></div>`).join(''):empty('No bus is running','Buses appear here when the driver starts the trip in the driver app.')}</div></div>
<div class="c"><h3>SOS history</h3>${tbl('csos',[{k:'at',l:'When',r:x=>fdt(x.at),v:x=>x.at},{k:'customer',l:'Passenger'},{k:'trip',l:'Trip'},{k:'note',l:'Problem'},{k:'status',l:'Status',r:x=>chip(x.status)}],SO,{noq:1,exp:false,nocrud:1,emptyT:'No SOS on your buses'})}</div></div>`});

