A.ou_save=()=>{if(!chk([['un','Name'],['ue','Email',x=>/^\S+@\S+\.\S+$/.test(x)?(DB.opUsers.some(u=>u.email===x)?'Already a user':''):'Enter a valid email']]))return;DB.opUsers.push({id:uid('OU'),operatorId:S.op,name:gv('un'),email:gv('ue'),role:gv('ur'),status:'INVITED',last:new Date().toISOString()});audit('Invited portal user',gv('ue'));closeModal();render();toast('Invitation sent')};
